<?php

namespace Teksite\FileManager\Support;


/**
 * Normalizes client supplied file names. The client name is only ever used for
 * display purposes; the stored name is always generated by the server.
 */
final class FilenameSanitizer
{
    /** Names shown in the UI: keeps Unicode letters, removes anything dangerous. */
    public static function display(string $name, int $max = 255): string
    {
        $name = self::stripControls($name);
        $name = str_replace(['\\', '/'], '-', $name);
        $name = trim($name, " .\t\n\r\0\x0B");

        if ($name === '') return 'file';

        return mb_strlen($name) > $max ? mb_substr($name, -$max) : $name;
    }

    /** Characters that are safe in a path segment (letters, digits, dot, dash, underscore). */
    public static function safe(string $name): string
    {
        $name = self::stripControls($name);

        return trim(preg_replace('/[^\p{L}\p{N}._-]+/u', '-', $name), '.-_');
    }

    /**
     * Every dot separated segment of the name, lowercased. Used to catch
     * "shell.php.jpg" style double extensions.
     *
     * @return list<string>
     */
    public static function extensions(string $name): array
    {
        $parts = explode('.', strtolower(self::stripControls($name)));
        array_shift($parts);

        return array_values(array_filter(array_map('trim', $parts), fn($p) => $p !== ''));
    }

    /** Removes control characters and Unicode bidi overrides (e.g. U+202E used to fake extensions). */
    private static function stripControls(string $value): string
    {
        $value = preg_replace('/[\x00-\x1F\x7F]/u', '', $value);

        return preg_replace('/[\x{200B}-\x{200F}\x{202A}-\x{202E}\x{2066}-\x{2069}\x{FEFF}]/u', '', $value);
    }
}
